});

test('createInvoice rejects invalid discountPercent', () => {
  const cases = [
    { sku: 'DEV-HOUR', qty: 1, discountPercent: -1 },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: 101 },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: 'invalid' },
