    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.number, 'INV-2024-0001');
});

test('issueInvoice assigns next number when others exist', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-20',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;

  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
  const result = issueInvoice(invoice, existingNumbers);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0003');
});

test('issueInvoice separates counters by year', () => {
  const invoice2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-12-31',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const invoice2025 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const existing2024 = ['INV-2024-0005'];

  const result2024 = issueInvoice(invoice2024, existing2024);
  assert.equal(result2024.value.number, 'INV-2024-0006');

  const result2025 = issueInvoice(invoice2025, existing2024);
  assert.equal(result2025.value.number, 'INV-2025-0001');
});

test('issueInvoice fails with NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
    number: 'INV-2024-0001',
  };

  const result = issueInvoice(invoice, []);

  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const originalStatus = invoice.status;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.number, undefined);
});

test('issueInvoice preserves invoice data', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-06-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2024-06-15');
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[1].qty, 5);
